import{_ as a,C as i,o as g,c as o,j as n,a as h,E as c}from"./chunks/framework.Bf1r8NYr.js";const x=JSON.parse('{"title":"Quiz tổng hợp — Workflow (10 câu, làm sau 6 bài)","description":"","frontmatter":{"quizKey":"final-quiz","questions":[{"id":"Q1.","text":"Sắp xếp đúng thứ tự workflow: (a) Chuẩn hóa, (b) Thiết kế & DMP, (c) Kết thúc/lưu trữ, (d) Thu thập, (e) FAIR & chia sẻ.","options":[{"key":"A","text":"b → d → a → e → c, theo tiến trình từ thiết kế đến lưu trữ."},{"key":"B","text":"d → b → a → c → e, bắt đầu bằng thu thập trước khi hoàn thiện kế hoạch."},{"key":"C","text":"b → a → d → e → c, đặt chuẩn hóa sớm hơn thu thập dữ liệu."},{"key":"D","text":"a → b → d → e → c, đặt chuẩn hóa trước phần thiết kế."}],"answer":"A","explain":"Workflow bắt đầu ở thiết kế và DMP, rồi thu thập, chuẩn hóa, FAIR/chia sẻ và kết thúc bằng lưu trữ hoặc hủy an toàn."},{"id":"Q2.","text":"Một nghiên cứu không viết DMP, thu thập xong mới nghĩ đến việc chia sẻ dữ liệu. Hậu quả nào có khả năng xảy ra nhất?","options":[{"key":"A","text":"Có thể mất thêm thời gian, nhưng nhiều quyết định quản trị khác vẫn giữ nguyên."},{"key":"B","text":"Thiếu metadata và biến không thống nhất, làm khó phê duyệt chia sẻ."},{"key":"C","text":"Có ít hậu quả vì quyết định chia sẻ có thể đưa ra ở cuối nghiên cứu."},{"key":"D","text":"Dữ liệu tự động trở nên FAIR vì đã được thu thập đầy đủ trong nghiên cứu."}],"answer":"B","explain":"Quyết định thượng nguồn bị bỏ qua có thể làm thiếu metadata, không nhất quán biến và hạn chế khả năng chia sẻ về sau."},{"id":"Q3.","text":"Bệnh viện A dùng FHIR để gửi dữ liệu cho bệnh viện B, rồi cả hai cùng phân tích trên OMOP CDM. Nhận định nào đúng?","options":[{"key":"A","text":"Phải chuyển sang CDISC trước, dù mục tiêu là trao đổi rồi phân tích quan sát."},{"key":"B","text":"Dùng thừa chuẩn; một chuẩn thường đủ cho cả trao đổi và phân tích."},{"key":"C","text":"Đúng vai trò: FHIR để trao đổi, OMOP để phân tích."},{"key":"D","text":"FHIR và OMOP thường khó dùng chung trong một quy trình liên cơ sở."}],"answer":"C","explain":"FHIR phục vụ trao đổi dữ liệu; OMOP phục vụ chuẩn hóa và phân tích dữ liệu quan sát."},{"id":"Q4.","text":"Dữ liệu khuyết vì bệnh nhân nặng không lấy được mẫu xét nghiệm. Cách xử lý đúng nhất là gì?","options":[{"key":"A","text":"Xóa toàn bộ bệnh nhân đó để bộ dữ liệu không còn ô khuyết."},{"key":"B","text":"Bỏ qua và không ghi lại nguyên nhân vì mẫu xét nghiệm chưa từng được lấy."},{"key":"C","text":"Điền giá trị trung bình cho nhiều bệnh nhân để giữ kích thước mẫu."},{"key":"D","text":"Xem xét MNAR, ghi giả định, chọn phương pháp và phân tích độ nhạy."}],"answer":"D","explain":"Cơ chế khuyết có thể liên quan đến mức độ bệnh; cần ghi giả định, chọn phương pháp phù hợp và kiểm tra độ nhạy."},{"id":"Q5.","text":"Khi xử lý dữ liệu cá nhân trong nghiên cứu, nguyên tắc nào phù hợp nhất?","options":[{"key":"A","text":"Chủ yếu áp dụng văn bản có tại thời điểm viết đề cương, ít rà soát về sau."},{"key":"B","text":"Có thể bỏ qua ngày hiệu lực nếu tên văn bản đã ghi trong DMP của nghiên cứu."},{"key":"C","text":"Đối chiếu văn bản hiện hành và ngày hiệu lực áp dụng cho bối cảnh nghiên cứu."},{"key":"D","text":"Chủ yếu tuân theo chính sách phần mềm thu thập dữ liệu, ít căn cứ khác."}],"answer":"C","explain":"Tên văn bản không đủ để xác định nghĩa vụ; cần kiểm tra văn bản hiện hành, ngày hiệu lực và phạm vi áp dụng."},{"id":"Q6.","text":"Một dataset đạt k-anonymity với k=5. Điều này đảm bảo điều gì?","options":[{"key":"A","text":"Dữ liệu đã được mã hóa và nhiều khóa liên kết đã bị loại bỏ."},{"key":"B","text":"Mỗi quasi-identifier xuất hiện ít nhất 5 lần; vẫn còn nguy cơ từ thông tin nền."},{"key":"C","text":"Không ai có thể tái định danh bằng bất kỳ cách nào, kể cả liên kết nguồn khác."},{"key":"D","text":"Dữ liệu được phép công khai mà không cần xét duyệt hoặc kiểm soát truy cập."}],"answer":"B","explain":"k-anonymity giới hạn liên kết trực tiếp, nhưng không loại bỏ mọi nguy cơ tái định danh hoặc suy luận thuộc tính nhạy cảm."},{"id":"Q7.","text":"Nhận định nào mô tả đầy đủ hơn yêu cầu để dữ liệu y sinh sẵn sàng cho AI?","options":[{"key":"A","text":"Dữ liệu cần lớn, sạch và ở định dạng bảng tính phổ biến để mô hình đọc được."},{"key":"B","text":"Dữ liệu chủ yếu cần có nhiều biến và ít ô trống, không cần provenance."},{"key":"C","text":"AI-ready cần FAIR, provenance, giải trình, quản trị và khả năng tính toán."},{"key":"D","text":"Dữ liệu nên được giữ kín để tránh rủi ro, không cần khả năng tái sử dụng."}],"answer":"C","explain":"AI-ready là yêu cầu đa chiều về khả năng tìm thấy, hiểu, giải trình, quản trị và tính toán, không chỉ là dung lượng hoặc độ sạch."},{"id":"Q8.","text":"Nghiên cứu kết thúc, nhóm xóa file dữ liệu bằng cách xóa thông thường trong hệ điều hành. Đủ chưa?","options":[{"key":"A","text":"Chưa chắc; xóa thông thường chưa đồng nghĩa khử hoặc hủy an toàn."},{"key":"B","text":"Đủ trong nhiều trường hợp vì tệp không còn hiển thị trong thư mục."},{"key":"C","text":"Không cần hủy, cứ giữ dữ liệu mãi mãi bất kể chính sách lưu giữ."},{"key":"D","text":"Cần quan tâm khi dataset có kích thước lớn hoặc nhiều tệp."}],"answer":"A","explain":"Cần có quy trình khử hoặc hủy phù hợp với loại lưu trữ, chính sách và yêu cầu áp dụng; xóa thông thường chưa đủ để kết luận an toàn."},{"id":"Q9.","text":"Trong workflow FAIRification 7 bước, đánh giá FAIR được dùng như thế nào?","options":[{"key":"A","text":"Đánh giá bước 1 để tìm khoảng cách và bước 7 để kiểm tra cải thiện."},{"key":"B","text":"Thường đánh giá một lần ở bước 7, sau khi đã hoàn tất nhiều thay đổi."},{"key":"C","text":"Chủ yếu đánh giá khi dữ liệu được công khai và không còn hạn chế."},{"key":"D","text":"Đánh giá FAIR thay thế cho việc lập kế hoạch và quản trị ở bước 1."}],"answer":"A","explain":"Đánh giá ban đầu định hướng kế hoạch, còn đánh giá lại ở bước 7 kiểm tra mức cải thiện và kết quả đạt được."},{"id":"Q10.","text":"Một học viên nói: “Dữ liệu của tôi đã FAIR nên tôi công khai toàn bộ lên mạng.” Sai ở đâu?","options":[{"key":"A","text":"Không sai, vì nhiều dữ liệu FAIR được công khai trên mạng."},{"key":"B","text":"FAIR chủ yếu áp dụng cho dữ liệu mở và không áp dụng cho dữ liệu sức khỏe."},{"key":"C","text":"Phải công khai mới gọi là FAIR, bất kể ràng buộc đạo đức hay pháp lý."},{"key":"D","text":"FAIR không đồng nghĩa mở hết; dữ liệu sức khỏe có thể kiểm soát truy cập."}],"answer":"D","explain":"FAIR yêu cầu khả năng tìm thấy, truy cập được theo điều kiện, liên thông và tái sử dụng; không buộc dữ liệu nhạy cảm phải mở công khai."}],"lessonAnswers":{"module-1-dmp":["A","B","C","D"],"module-2-collection":["B","C","D","A"],"module-3-standards":["C","D","A","B"],"module-4-quality":["D","A","B","C"],"module-5-privacy":["A","B","C","D"],"module-6-fair-ai":["B","C","D","A"]}},"headers":[],"relativePath":"course/final-quiz.md","filePath":"course/final-quiz.md"}'),k={name:"course/final-quiz.md"};function l(r,t,y,s,p,d){const u=i("Quiz"),e=i("QuizResult");return g(),o("div",null,[t[0]||(t[0]=n("h1",{id:"quiz-tong-hop-—-workflow-10-cau-lam-sau-6-bai",tabindex:"-1"},[h("Quiz tổng hợp — Workflow (10 câu, làm sau 6 bài) "),n("a",{class:"header-anchor",href:"#quiz-tong-hop-—-workflow-10-cau-lam-sau-6-bai","aria-label":'Permalink to "Quiz tổng hợp — Workflow (10 câu, làm sau 6 bài)"'},"​")],-1)),c(u),c(e),t[1]||(t[1]=n("p",null,[n("strong",null,"Cách tính điểm:"),h(" mỗi câu 1 điểm, tổng 34 câu (24 câu theo bài + 10 câu tổng hợp). Đạt khi ≥ 24/34 "),n("strong",null,"và đúng ít nhất 2/3 câu Q1–Q3"),h(" của quiz tổng hợp. Học viên nên làm quiz tổng hợp tối đa 2 lần như hướng dẫn tự học; site tĩnh không cưỡng chế giới hạn này.")],-1))])}const v=a(k,[["render",l]]);export{x as __pageData,v as default};
